pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Favor items that fit well in the current bin
    if item_size <= bin_residual {
        score += (1.0 - (bin_residual as f64 / bin_capacity as f64).powi(2)) * 0.8;
    } else {
        score -= 1.5;
    }

    // Penalize bins with low residual space after placing items
    let residual_penalty = if post_residual < mean_residual * 1.3 {
        (mean_residual * 1.3 - post_residual) as f64 / bin_capacity as f64 * post_residual as f64 / bin_capacity as f64 * 0.75
    } else {
        (post_residual as f64 - mean_residual * 1.3) as f64 / bin_capacity as f64 * post_residual as f64 / bin_capacity as f64 * 0.75
    };
    score -= residual_penalty;

    // Reward bins that have enough space for the next item without opening a new bin
    if next_item_size > 0 && fitting_bins_count > 0 && post_residual >= next_item_size {
        score += (post_residual as f64 - next_item_size as f64) / bin_capacity as f64 * (1.0 + post_residual as f64 / bin_capacity as f64) * 0.95;
    } else {
        score -= (next_item_size as f64 - post_residual) as f64 / bin_capacity as f64 * (1.0 + next_item_size as f64 / bin_capacity as f64) * 0.95;
    }

    // Penalize creating new bins
    let open_bins_penalty = if open_bins_count < total_items / 2 {
        open_bins_count as f64 / (total_items / 2) as f64 * open_bins_count as f64 / (total_items / 2) as f64 * 0.85
    } else {
        (open_bins_count - total_items / 2) as f64 / (total_items / 2) as f64 * (open_bins_count - total_items / 2) as f64 / (total_items / 2) as f64 * 0.85
    };
    score -= open_bins_penalty;

    // Reward filling bins to capacity
    if post_residual == 0 {
        score += 1.3;
    } else {
        score -= post_residual as f64 / bin_capacity as f64 * post_residual as f64 / bin_capacity as f64 * 0.85;
    }

    // Lookahead reward for fitting multiple items in the current bin
    let lookahead_reward = if step_index < total_items - 2 && post_residual >= next_item_size + bin_residual {
        let remaining_space = post_residual - next_item_size;
        if remaining_space >= item_size {
            (remaining_space as f64 - item_size as f64) / bin_capacity as f64 * (1.0 + remaining_space as f64 / bin_capacity as f64) * 0.95;
        } else {
            0.0
        }
    } else {
        0.0
    };
    score += lookahead_reward;

    score
}

